Tool response:
Tool: find_part_cross_references
Description: Find all aftermarket cross-references for the specified part number that are certified
to fit 2019-2023 Ford F-150 models with 3.5L EcoBoost engines. Returns corresponding
OEM numbers, descriptions, and warehouse availability status.
Parameters:
    {
      "type": "object",
      "properties": {
        "part_number": {
          "type": "string",
          "description": "Aftermarket part number to search for cross-references",
          "title": "Part Number"
        },
        "make": {
          "type": "string",
          "description": "Vehicle make (e.g., 'Ford')",
          "title": "Make"
        },
        "model": {
          "type": "string",
          "description": "Vehicle model (e.g., 'F-150')",
          "title": "Model"
        },
        "engine": {
          "type": "string",
          "description": "Engine specification (e.g., '3.5L EcoBoost V6')",
          "title": "Engine"
        },
        "start_year": {
          "type": "integer",
          "description": "Starting year of vehicle compatibility range",
          "title": "Start Year"
        },
        "end_year": {
          "type": "integer",
          "description": "Ending year of vehicle compatibility range",
          "title": "End Year"
        }
      },
      "required": [
        "part_number",
        "make",
        "model",
        "engine",
        "start_year",
        "end_year"
      ]
    }
